	volume_z168: ["거래량 z", "1시간 거래량(로그)의 168시간 z점수"],
	funding_last: ["최근 펀딩", "마지막 정산 펀딩비"],
	premium_1h: ["베이시스 1시간", "직전 1시간 프리미엄"],
	premium_24h: ["베이시스 24시간", "프리미엄 24시간 평균"],
	oi_chg_4h: ["OI 4시간 변화", "미결제약정 4시간 로그 변화"],
};

export const FAMILY_LABEL: Record<string, string> = {
	price: "가격·거래량",
	funding: "펀딩",
	basis: "베이시스",
	oi: "미결제약정",
	long_short: "롱숏비",
	kimchi: "김프",
	expert: "워뇨띠 체결",
	mimic: "모방 지표",
};

export const featureName = (f: ScreenFeature) => FEATURE_LABEL[f.feature]?.[0] ?? f.feature;
export const featureDef = (f: ScreenFeature) => FEATURE_LABEL[f.feature]?.[1] ?? "";

/** Badge kind of a screen verdict (color plus the verdict word). */
export function verdictKind(v: ScreenVerdict): Verdict | "waiting" {
	if (v === "채택") return "passed";
	if (v === "기각") return "rejected";
	if (v === "판정 불가") return "waiting";
	return "undecided";
}

export function stateKind(s: ScreenDoc["state"]): Verdict {
	return s === "연구통과" ? "passed" : s === "연구기각" ? "rejected" : "undecided";
}

export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

export function num(v: number | null | undefined, digits = 3): string {
	if (v == null || !Number.isFinite(v)) return "—";
	const s = v.toFixed(digits);
	return v > 0 ? `+${s}` : s.replace("-", "−");
}

export function pctOf(v: number | null | undefined, digits = 1): string {
	if (v == null || !Number.isFinite(v)) return "—";
	const s = (v * 100).toFixed(digits);
	return v > 0 ? `+${s}%` : `${s.replace("-", "−")}%`;
}

/** Gate nodes for GateFlow: names and rules from the document, status from `gate_status`. */
export function screenGates(doc: ScreenDoc): Gate[] {
	return doc.gates.map((g) => {
		const s = doc.gate_status.find((x) => x.id === g.id);
		return {
			id: g.id,
			name: g.name,
			definition: `${g.id}: ${g.rule}.`,
			status: s?.status ?? "waiting",
			reason: s?.reason ?? "",
		};
	});
}

/**
 * The matrix: one row per candidate at horizon `h` ("lead" = the horizon its verdict is about), one
 * column per test year; a cell is that year's signed rank IC ×100 (0.10 shows as +10).
 */
export function screenMatrix(doc: ScreenDoc, h: "lead" | number = "lead"): RunMatrix {
	const years = new Set<number>();
	for (const f of doc.features) for (const t of f.trials) for (const fold of t.folds) years.add(fold.year);
	const folds = [...years].sort().map((year) => ({ id: String(year), year }));
	return {
		phase: "screen",
		stresses: [{ id: "ic", label: "" }],
		folds,
		rows: doc.features.map((f) => {
			const trial = h === "lead" ? leadTrial(f) : f.trials.find((t) => t.h === h);
			return {
				candidate: f.code,
				label: trial ? `${trial.h}${doc.unit}` : "—",
				cells: (trial?.folds ?? [])
					.filter((fold) => fold.ic != null)
					.map((fold) => ({
						stress: "ic",
						year: fold.year,
						diff: fold.ic! * 100,
						gate0: "passed" as const,
					})),
			};
		}),
		note: "",
	};
}

