/** Cumulative-return curve in percent; a missing point carries over the previous value. */
export function curveView(trial: ScreenTrial | undefined | null): CurveView | null {
	const curve = trial?.curve;
	if (!curve || !curve.t || curve.t.length < 2) return null;
	const toPct = (values: (number | null)[] | undefined) => {
		let last = 0;
		return (values ?? []).map((v) => {
			if (v == null || !Number.isFinite(v)) return last;
			last = v * 100;
			return last;
		});
	};
	const rule = toPct(curve.rule);
	const hold = toPct(curve.hold);
	const all = [...rule, ...hold];
	return {
		t: curve.t,
		rule,
		hold,
		ticks: niceTicks(Math.min(...all), Math.max(...all)),
		labels: curve.t.map(dateLabel),
	};
}

export interface ScreenRuleTile {
	id: string;
	group: string;
	name: string;
	label: string;
	tip: string;
}

/** The screen's trading rule as tiles: direction, indicator, (regime gate), fill cost and holding horizon. */
export function screenRule(doc: ScreenDoc, f: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign != null;
	const sign = doc.fixed_sign ?? trial.train_sign ?? 1;
	const longAbove = sign >= 0;
	const foldSigns = new Set((trial.folds ?? []).map((fold) => fold.train_sign));
	const changed = foldSigns.size > 1;
	const directionLabel = changed ? "부호 바뀜" : fixed ? "순방향" : sign < 0 ? "역추세" : "순방향";
	const directionTip = fixed
		? `방향 부호 ${sign > 0 ? "+1" : "-1"}로 고정된 규칙이다. 기준(0) 위면 ${longAbove ? "롱" : "숏"}, 아래면 ${longAbove ? "숏" : "롱"}이다.`
		: changed
			? "학습 구간 연도마다 방향 부호가 바뀌었다. 해마다 같은 말을 하지 않는다."
			: sign < 0
				? "학습 때 방향 부호가 음수라, 기준 위면 숏이고 아래면 롱인 역추세 규칙이다."
				: "학습 때 방향 부호가 양수라, 기준 위면 롱이고 아래면 숏인 순방향 규칙이다.";
	const tiles: ScreenRuleTile[] = [
		{
			id: "direction",
			group: "entry",
			name: longAbove ? "기준 위면 롱" : "기준 위면 숏",
			label: directionLabel,
			tip: directionTip,
		},
		{
			id: "indicator",
			group: "entry",
			name: featureName(f),
			label: f.tradeable === false ? "참고 지표" : "매매 지표",
			tip:
				f.tradeable === false
					? "그의 체결은 실시간으로 공개되지 않는다. 따라갈 수 있었다면 어땠나를 보는 참고 행이다."
					: featureDef(f) || `${f.feature} 지표값이 기준을 넘으면 진입한다.`,
		},
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "하락장에서만",
			label: "레짐 게이트",
			tip: "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다.",
		});
	}
	const bp = Math.round((doc.cost_per_side ?? 0) * 1e4);
	tiles.push(
		{
			id: "fill",
			group: "fill",
			name: `편도 ${bp}bp`,
			label: "체결 비용",
			tip: `편도 ${bp}bp의 비용을 빼고 계산했다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "보유 기간",
			tip: `진입한 뒤 ${trial.h}${doc.unit} 뒤에 청산한다.`,
		},
	);
	return tiles;
}

