	funding_7d: ["펀딩 7일", "펀딩비 7일 평균"],
	funding_z90: ["펀딩 z", "펀딩 1일의 90일 z점수"],
	premium_1d: ["베이시스 1일", "무기한 가격의 지수 대비 프리미엄 24시간 평균"],
	premium_z90: ["베이시스 z", "베이시스 1일의 90일 z점수"],
	oi_chg_1d: ["OI 1일 변화", "미결제약정 1일 로그 변화"],
	oi_chg_7d: ["OI 7일 변화", "미결제약정 7일 로그 변화"],
	oi_x_trend_7d: ["OI × 추세", "OI 7일 변화에 7일 가격 방향 부호를 곱한 값"],
	top_position_ls_z90: ["상위 트레이더 롱숏 z", "상위 계정 포지션 롱숏비의 90일 z점수"],
